(() => {
  const IDIOMAS = ["pt", "en", "es"];
  const idx = { en: 0, es: 1 };
  const norm = (s) => s.replace(/\s+/g, " ").trim();
  const ALVOS = "title,h1,h2,h3,h4,p,li,summary,figcaption,a,span,small,strong,b,button,dt,dd,blockquote";
  const INLINE = new Set(["EM", "B", "STRONG", "BR", "I"]);

  // guarda o português original de cada ponto traduzível, uma única vez
  const blocos = [];   // elementos com HTML inline (em, b, strong, br)
  const textos = [];   // nós de texto soltos (ao lado de ícones, spans etc.)
  document.querySelectorAll(ALVOS).forEach((el) => {
    if (el.closest("svg, script, .idioma")) return;
    const soInline = [...el.children].every((c) => INLINE.has(c.tagName));
    const chave = norm(el.innerHTML);
    if (soInline && T[chave]) { blocos.push({ el, pt: el.innerHTML, chave }); return; }
    el.childNodes.forEach((n) => {
      if (n.nodeType === 3 && norm(n.textContent) && T[norm(n.textContent)]) {
        textos.push({ n, pt: n.textContent, chave: norm(n.textContent) });
      }
    });
  });
  // textos dos selos (dentro de SVG)
  document.querySelectorAll("textPath").forEach((n) => {
    if (T[norm(n.textContent)]) textos.push({ n, pt: n.textContent, chave: norm(n.textContent) });
  });
  const attrs = [];
  document.querySelectorAll("[alt],[aria-label],meta[name=description],meta[property^='og:']").forEach((el) => {
    ["alt", "aria-label", "content"].forEach((a) => {
      const v = el.getAttribute(a);
      if (v && ATTR[norm(v)]) attrs.push({ el, a, pt: v, chave: norm(v) });
    });
  });
  const tituloPt = document.title;
  const was = [...document.querySelectorAll("[data-wa]")].map((el) => ({ el, msg: el.dataset.wa || "" }));

  function aplica(lang) {
    const i = idx[lang];
    blocos.forEach((b) => { b.el.innerHTML = lang === "pt" ? b.pt : T[b.chave][i]; });
    textos.forEach((t) => {
      if (lang === "pt") { t.n.textContent = t.pt; return; }
      const antes = t.pt.match(/^\s*/)[0], depois = t.pt.match(/\s*$/)[0];
      t.n.textContent = antes + T[t.chave][i] + depois;
    });
    attrs.forEach((x) => x.el.setAttribute(x.a, lang === "pt" ? x.pt : ATTR[x.chave][i]));
    document.title = lang === "pt" ? tituloPt : (ATTR[norm(tituloPt)] || [tituloPt, tituloPt])[i];
    document.documentElement.lang = { pt: "pt-BR", en: "en", es: "es" }[lang];

    // WhatsApp na língua de quem escreve
    was.forEach(({ el, msg }) => {
      let texto;
      if (!msg) texto = lang === "pt" ? WA_PT_PADRAO : WA[""][i];
      else texto = OLA[lang] + (lang === "pt" ? msg : (WA[msg] || [msg, msg])[i]);
      el.href = "https://wa.me/5511914801043?text=" + encodeURIComponent(texto);
      el.target = "_blank";
      el.rel = "noopener";
    });

    document.querySelectorAll(".idioma button").forEach((b) => b.setAttribute("aria-pressed", b.dataset.lang === lang));
    try { localStorage.setItem("kc-idioma", lang); } catch (e) {}
    const url = new URL(location.href);
    if (lang === "pt") url.searchParams.delete("lang"); else url.searchParams.set("lang", lang);
    history.replaceState(null, "", url);
    dispatchEvent(new Event("resize")); // realinha a hero ao novo tamanho do título
  }

  document.querySelectorAll(".idioma button").forEach((b) => b.addEventListener("click", () => aplica(b.dataset.lang)));

  // idioma inicial: ?lang= → escolha salva → idioma do navegador
  let inicial = new URLSearchParams(location.search).get("lang");
  if (!IDIOMAS.includes(inicial)) { try { inicial = localStorage.getItem("kc-idioma"); } catch (e) {} }
  if (!IDIOMAS.includes(inicial)) {
    const nav = (navigator.language || "pt").slice(0, 2);
    inicial = IDIOMAS.includes(nav) ? nav : "pt";
  }
  aplica(inicial);
})();
